/** Footer row alignment for muted chrome. `between` keeps help/link + CTA spreads; `end` groups CTAs like step footers. */
footerAlign?: "between" | "end";
/** Footer strip — typically a help link + primary CTA. */
footer?: ReactNode;

export function DetailCard({
  tone = "muted",
  leadingInset,
  headerSlot,
  title,
  description,
  watermark,
  hideWatermark = false,
  footer,
  footerAlign = "between",
  footerClassName,
  contentClassName,
  children,
  className,
}: DetailCardProps) {
  const watermarkNode = hideWatermark ? null : (watermark ?? defaultWatermark);
  const mutedChrome = tone === "muted";

  const headerClass = mutedChrome
    ? "gap-1 border-b bg-muted/40 p-region [.border-b]:pb-region"
    : cn("gap-region pb-section shrink-0", "sm:px-boundary sm:pt-boundary");

  const defaultHeader = (
    <>
      {title != null && title !== "" ? <H2>{title}</H2> : null}
      {description ? (
        <CardDescription className="text-base leading-normal">{description}</CardDescription>
      ) : null}
    </>
  );

  const footerClass = mutedChrome
    ? footerAlign === "between"
      ? "flex-wrap-reverse justify-end gap-component border-t bg-muted/40 sm:flex-nowrap sm:justify-between"
      : "flex flex-row flex-wrap items-center justify-end gap-component border-t bg-muted/40 sm:flex-nowrap"
    : "flex flex-row flex-wrap items-center justify-end gap-component";

