import { Alert01Icon } from "@hugeicons/core-free-icons";
import { HugeiconsIcon } from "@hugeicons/react";
import {
  Alert,
  AlertDescription,
  AlertTitle,
  Badge,
  Field,
  FieldContent,
  FieldLabel,
  Input,
  Progress,
  cn,
} from "@procertus-ui/ui";
import { PrototypeCard } from "@procertus-ui/ui-pt1-prototype";
import type { OnboardingRegistrationLayoutModel } from "../../../onboarding/use-onboarding-registration-layout-model";
import { COUNTRY_SELECT_NONE } from "../../../onboarding/onboarding-constants";
import {
  firmaAddressSubformValue,
  registrationIsoCodeFromDutchCountryLabel,
} from "../../../onboarding/onboarding-flow-helpers";
import type { OnboardingRequestOrigin } from "../../../onboarding/onboarding-request-origin";
import {
  ONBOARDING_REQUEST_ORIGIN_IDS,
  isFirmaCountryLockedToRequestOrigin,
} from "../../../onboarding/onboarding-request-origin";
import { RequestOriginFlag } from "../../../onboarding/onboarding-request-origin-flag";
import {
  VAT_LOOKUP_OUTCOME_LABELS,
  VAT_PROTOTYPE_PRESETS,
  type VatLookupMockOutcome,
} from "../../../onboarding/lib/vatPrototypePresets";
import {
  IdentificatieAddressSubform,
} from "../../../onboarding/identificatie-subforms";
import {
  OnboardingCompanyPrefillSkeleton,
  OnboardingContextField,
} from "../shared/onboarding-shared-fields";

export type OnboardingCompanyZetelStepProps = { model: OnboardingRegistrationLayoutModel };

export function OnboardingCompanyZetelStep({ model }: OnboardingCompanyZetelStepProps) {
  const {
    context,
    updateContext,
    patchContext,
    companyLookupPhase,
    lookupProgress,
    lookupStepIndex,
    vatLookupStepLabels,
    companyPrefillFieldKeys,
    companyFieldsResolvedInSimulation,
    vatNumberForDisplay,
    emailForDisplay,
    activeVatPreset,
    prototypeVatPresetId,
    requestOrigin,
    countrySelectOptions,
    countrySelectValue,
    companyHints,
    companySourceCountryLabel,
  } = model;

  const firmaCountryLocked = isFirmaCountryLockedToRequestOrigin(requestOrigin);
  const activePreset =
    activeVatPreset ??
    (prototypeVatPresetId ? VAT_PROTOTYPE_PRESETS.find((p) => p.id === prototypeVatPresetId) : undefined);

  return (
    <>
      <div className="rounded-lg border border-border bg-muted/30 px-4 py-3">
        <div className="grid gap-4 sm:grid-cols-3">
          <div>
            <p className="text-xs font-medium tracking-wide text-muted-foreground uppercase">
              Btw-nummer
            </p>
            <p className="mt-1 font-mono text-sm text-foreground">{vatNumberForDisplay || "—"}</p>
          </div>
          <div>
            <p className="text-xs font-medium tracking-wide text-muted-foreground uppercase">
              E-mail
            </p>
            <p className="mt-1 break-all text-sm text-foreground">{emailForDisplay || "—"}</p>
          </div>
          <div>
            <p className="text-xs font-medium tracking-wide text-muted-foreground uppercase">
              Land
            </p>
            <div className="mt-1 flex min-w-0 items-center gap-2 text-sm text-foreground">
              {requestOrigin !== "" &&
              ONBOARDING_REQUEST_ORIGIN_IDS.includes(requestOrigin as OnboardingRequestOrigin) ? (
                <RequestOriginFlag
                  origin={requestOrigin as OnboardingRequestOrigin}
                  compact
                  className="shrink-0"
                />
              ) : null}
              <span className="min-w-0 break-words">{companySourceCountryLabel}</span>
            </div>
          </div>
        </div>
      </div>

      {companyLookupPhase === "loading" ? (
        <div className="space-y-5">
          <div className="space-y-2">
            <div className="flex items-center justify-between gap-2 text-sm">
              <span className="font-medium text-foreground">Bezig met opzoeken</span>
              <span className="tabular-nums text-muted-foreground">{Math.round(lookupProgress)}%</span>
            </div>
            <Progress
              value={lookupProgress}
              className="h-2"
              aria-label="Voortgang opzoeken bedrijfsgegevens"
            />
          </div>
          <ul className="space-y-2.5" aria-live="polite">
            {vatLookupStepLabels.map((item, index) => {
              const done = lookupStepIndex > index;
              const active = lookupStepIndex === index;
              return (
                <li
                  key={item.id}
                  className={cn(
                    "flex items-center gap-3 text-sm transition-colors",
                    done || active ? "text-foreground" : "text-muted-foreground",
                  )}
                >
                  <span
                    className={cn(
                      "size-2 shrink-0 rounded-full",
                      done
                        ? "bg-primary"
                        : active
                          ? "bg-primary animate-pulse"
                          : "bg-muted-foreground/30",
                    )}
                    aria-hidden
                  />
                  <span>{item.label}</span>
                </li>
              );
            })}
          </ul>
          <OnboardingCompanyPrefillSkeleton
            prefilledKeys={companyPrefillFieldKeys}
            resolvedKeys={companyFieldsResolvedInSimulation}
          />
        </div>
      ) : null}

      {companyLookupPhase === "ready" && activePreset ? (
        <>
          <Alert variant="warning">
            <HugeiconsIcon icon={Alert01Icon} aria-hidden className="size-4 shrink-0" />
            <AlertTitle className="flex flex-wrap items-center gap-2">
              <span>{activePreset.outcomeLabel}</span>
              <Badge variant="warning">
                {VAT_LOOKUP_OUTCOME_LABELS[activePreset.mock.outcome as VatLookupMockOutcome]}
              </Badge>
            </AlertTitle>
            <AlertDescription>{activePreset.outcomeMessage}</AlertDescription>
          </Alert>
          {activePreset.demoSupplementsOrgAddressFromEmailDomain ? (
            <PrototypeCard
              title="Aanvulling vanuit uw e-mail"
              description={
                <>
                  Voor dit voorbeeld ontvangen we geen bedrijfsnaam en volledig adres bij alleen uw
                  nummer. Waar mogelijk vullen we ze aan met het e-mailadres dat u opgaf. Controleer
                  alles; bij een algemeen mailboxadres vult u zelf aan.
                </>
              }
              cardContentClassName="hidden"
            >
              {null}
            </PrototypeCard>
          ) : null}
          <div className="space-y-1">
            <h3 className="text-sm font-semibold tracking-tight text-foreground">
              Maatschappelijke zetel
            </h3>
            <p className="text-xs leading-relaxed text-muted-foreground">
              Dit zijn de officiële gegevens van uw hoofdrechtspersoon, zoals die aan uw
              identificatienummer gekoppeld zijn. Ze kunnen afwijkend zijn van waar productie of
              certificatie fysiek plaatsvindt.
            </p>
          </div>
          <div className="grid gap-4 md:grid-cols-2">
            <OnboardingContextField
              id="organizationName"
              label="Juridische naam van de onderneming (zetel)"
              value={context.organizationName}
              onChange={updateContext}
              placeholder="Officiële bedrijfsnaam"
              description={companyHints.organizationName}
            />
            <Field>
              <FieldLabel htmlFor="firmaPhone">Telefoon firma</FieldLabel>
              <FieldContent>
                <Input
                  id="firmaPhone"
                  type="tel"
                  value={context.firmaPhone}
                  onChange={(e) => updateContext("firmaPhone", e.target.value)}
                  placeholder="Hoofdnummer organisatie"
                />
              </FieldContent>
            </Field>
          </div>
          <IdentificatieAddressSubform
            idPrefix="firma-address"
            value={firmaAddressSubformValue(context)}
            onChange={(v) => {
              const iso = registrationIsoCodeFromDutchCountryLabel(v.country.trim()) || "";
              patchContext({
                addressStreet: v.street,
                addressHouseNumber: v.houseNumber,
                addressPostalCode: v.postalCode,
                addressCity: v.locality,
                country: v.country,
                addressCountryCode: iso,
              });
            }}
            countryOptions={countrySelectOptions}
            countrySelectValue={countrySelectValue}
            onCountryChange={(v) => updateContext("country", v === COUNTRY_SELECT_NONE ? "" : v)}
            countrySelectMode={firmaCountryLocked ? "locked" : "editable"}
            showCountryCodeField={false}
            fieldHints={{
              street: companyHints.addressStreet,
              country: companyHints.country,
            }}
          />
        </>
      ) : null}
    </>
  );
}

/** Presentational onboarding sub-step: certificatie / juridische entiteit vs vestigingen. */
/* eslint-disable eslint/no-unused-vars -- align import block across registration steps */
import {
  Field,
  FieldContent,
  FieldDescription,
  FieldLabel,
  Input,
  Label,
  RadioGroup,
  RadioGroupItem,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@procertus-ui/ui";
import { DraftCardDescription } from "../../certification-request-wizard/draft-selection-presentation";
import { useEffect, useMemo } from "react";
import { registrationIsoCodeFromDutchCountryLabel } from "../../../onboarding/lib/vatPrototypePresets";
import {
  formatPostalAddressDisplay,
  formatVestigingRegistryOptionLabel,
  isOnboardingVestigingCaptureComplete,
  syncOnboardingVestigingenOnePerRegistrationDraft,
  vestigingAddressSubformValue,
} from "../../../onboarding/onboarding-flow-helpers";
import type { OnboardingRegistrationLayoutModel } from "../../../onboarding/use-onboarding-registration-layout-model";
import { COUNTRY_SELECT_NONE } from "../../../onboarding/onboarding-constants";
import {
  IdentificatieAddressSubform,
} from "../../../onboarding/identificatie-subforms";
import { SubformCompletionBadge } from "../../../onboarding/subform-completion-badge";
import { personFormCardClassName } from "../../../onboarding/person-form-card-variants";

export type OnboardingCompanyLegalEntitiesStepProps = {
  model: OnboardingRegistrationLayoutModel;
};

export function OnboardingCompanyLegalEntitiesStep({
  model,
}: OnboardingCompanyLegalEntitiesStepProps) {
  const {
    companyLookupPhase,
    context,
    patchContext,
    legalEntityFieldBase,
    draftsInRegistrationScope,
    countrySelectOptions,
    activeVatPreset,
  } = model;

  const registrationDraftScopeKey = useMemo(
    () => draftsInRegistrationScope.map((d) => d.id).join("|"),
    [draftsInRegistrationScope],
  );

  useEffect(() => {
    if (context.headOfficeIsCertificationLegalEntity !== "no") return;
    if (draftsInRegistrationScope.length === 0) return;
    const synced = syncOnboardingVestigingenOnePerRegistrationDraft(
      draftsInRegistrationScope,
      context.onboardingVestigingen,
      context.certificationInquiryVestigingId,
    );
    const sameOrderedIds =
      synced.onboardingVestigingen.length === context.onboardingVestigingen.length &&
      synced.onboardingVestigingen.every((v, i) => v.id === context.onboardingVestigingen[i]?.id);
    const mapAligned =
      sameOrderedIds &&
      draftsInRegistrationScope.every((d, i) => {
        const want = synced.onboardingVestigingen[i]?.id ?? "";
        return (context.certificationInquiryVestigingId[d.id] ?? "").trim() === want;
      });
    if (mapAligned) return;
    patchContext({
      onboardingVestigingen: synced.onboardingVestigingen,
      certificationInquiryVestigigId: synced.certificationInquiryVestigingId,
    });
  }, [
    context.certificationInquiryVestigingId,
    context.headOfficeIsCertificationLegalEntity,
    context.onboardingVestigingen,
    draftsInRegistrationScope,
    patchContext,
    registrationDraftScopeKey,
  ]);

  if (companyLookupPhase !== "ready" || !activeVatPreset) {
    return (
      <p className="text-sm text-muted-foreground">
        Dit scherm wordt actief nadat het opzoeken van uw bedrijfsgegevens is afgerond op de vorige
        stap.
      </p>
    );
  }

  const severalCertificationsInScope = draftsInRegistrationScope.length > 1;
  const headOfficeLegalEntityName = context.organizationName.trim();
  const headOfficeLegalEntityAddress = formatPostalAddressDisplay(context);

  return (
    <>
      <div className="space-y-6">
        <div className="space-y-3">
          <h3 className="text-sm font-semibold tracking-tight text-foreground">
            Certificatie en juridische entiteit
          </h3>
          <p className="text-xs leading-relaxed text-muted-foreground">
            U ziet onderaan een tabel of formulieren met{" "}
            <span className="font-medium text-foreground">welke aanvragen</span> in dit dossier zitten
            en <span className="font-medium text-foreground">welke juridische entiteit</span> daarbij
            hoort. Kiest u voor de maatschappelijke zetel: die gegevens gelden voor het dossier zoals op
            de vorige stap. Kiest u voor aparte vestigingen: elk formulier staat automatisch gekoppeld
            aan één aanvraag — er is geen knop om een vestiging toe te voegen.
          </p>
        </div>

        {draftsInRegistrationScope.length === 0 ? (
          <p className="rounded-md border border-dashed border-border bg-muted/20 px-3 py-2 text-xs text-muted-foreground">
            Er zijn in dit dossier geen gekozen certificatieaanvragen om te tonen. Koppel aanvragen
            via nazicht als dat nodig is. Beantwoord hieronder hoe uw organisatie optreedt wanneer u
            wél aanvragen in het dossier opneemt.
          </p>
        ) : null}

        <Field>
          <FieldLabel id={`${legalEntityFieldBase}-legend`}>
            {severalCertificationsInScope
              ? "Kan de hierboven geregistreerde maatschappelijke zetel optreden als juridisch aanspreekpunt voor al uw certificatieaanvragen in dit dossier (zelfde gegevens als de zetel, geen aparte vestiging)?"
              : "Kan de hierboven geregistreerde maatschappelijke zetel optreden als juridisch aanspreekpunt voor uw certificatieaanvraag in dit dossier (zelfde gegevens als de zetel, geen aparte vestiging)?"}
          </FieldLabel>
          <FieldContent>
            <RadioGroup
              className="gap-3"
              aria-labelledby={`${legalEntityFieldBase}-legend`}
              value={
                context.headOfficeIsCertificationLegalEntity === ""
                  ? undefined
                  : context.headOfficeIsCertificationLegalEntity
              }
              onValueChange={(v) => {
                if (v === "yes") {
                  patchContext({
                    headOfficeIsCertificationLegalEntity: "yes",
                    onboardingVestigingen: [],
                    certificationInquiryVestigingId: {},
                  });
                } else if (v === "no") {
                  patchContext({
                    headOfficeIsCertificationLegalEntity: "no",
                    ...syncOnboardingVestigingenOnePerRegistrationDraft(
                      draftsInRegistrationScope,
                      context.onboardingVestigingen,
                      context.certificationInquiryVestigingId,
                    ),
                  });
                }
              }}
            >
              <div className="flex items-center gap-2">
                <RadioGroupItem value="yes" id={`${legalEntityFieldBase}-yes`} />
                <Label htmlFor={`${legalEntityFieldBase}-yes`} className="cursor-pointer font-normal">
                  Ja, de zetel is het juridisch aanspreekpunt voor elke getoonde aanvraag
                </Label>
              </div>
              <div className="flex items-center gap-2">
                <RadioGroupItem value="no" id={`${legalEntityFieldBase}-no`} />
                <Label htmlFor={`${legalEntityFieldBase}-no`} className="cursor-pointer font-normal">
                  Nee, per aanvraag registreer ik een andere juridische entiteit (vestiging)
                </Label>
              </div>
            </RadioGroup>
            <FieldDescription>
              {severalCertificationsInScope
                ? 'Kiest u "nee": er opent automatisch per aanvraag een formulier — geen aparte knop nodig.'
                : 'Kiest u "nee": het formulier voor uw vestiging opent automatisch onder de aanvraag.'}
            </FieldDescription>
          </FieldContent>
        </Field>

        {draftsInRegistrationScope.length > 0 && context.headOfficeIsCertificationLegalEntity === "yes" ? (
          <div className="space-y-5">
            <div className="rounded-lg border border-border bg-muted/20 px-4 py-4">
              <p className="text-xs font-medium uppercase tracking-wide text-muted-foreground">
                Maatschappelijke zetel (geldt voor dit hele dossier)
              </p>
              <p className="mt-2 text-sm font-semibold text-foreground">
                {headOfficeLegalEntityName.length > 0 ? headOfficeLegalEntityName : "—"}
              </p>
              <p className="mt-1 text-xs leading-relaxed text-muted-foreground">
                {headOfficeLegalEntityAddress}
              </p>
            </div>
            <div className="overflow-x-auto rounded-lg border border-border">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead className="min-w-[200px]">Certificatie / product</TableHead>
                    <TableHead className="min-w-[220px]">Toegewezen juridische entiteit</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {draftsInRegistrationScope.map((draft) => (
                    <TableRow key={draft.id}>
                      <TableCell className="align-top">
                        <p className="text-sm font-medium text-foreground">
                          {draft.shortLabel || draft.label}
                        </p>
                        <div className="mt-1 text-xs text-muted-foreground [&_.font-medium]:text-foreground">
                          <DraftCardDescription draft={draft} />
                        </div>
                      </TableCell>
                      <TableCell className="align-top text-sm text-foreground">
                        <span className="font-medium">
                          {headOfficeLegalEntityName || "Maatschappelijke zetel"}
                        </span>
                        <span className="mt-1 block text-xs font-normal text-muted-foreground">
                          Maatschappelijke zetel — adres zoals vastgelegd op de vorige stap (één keer
                          voor alle aanvragen).
                        </span>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          </div>
        ) : null}

        {draftsInRegistrationScope.length > 0 && context.headOfficeIsCertificationLegalEntity === "no" ? (
          <div className="space-y-6">
            <p className="text-xs leading-relaxed text-muted-foreground">
              Voor{" "}
              <span className="font-medium text-foreground">elke onderstaande aanvraag</span> vult u een
              aparte juridische entiteit (vestiging) in, naast de maatschappelijke zetel en zonder apart
              btw-nummer. De formulieren staan direct klaar — u hoeft geen vestiging meer toe te voegen.
            </p>
            <div className="space-y-8">
              {draftsInRegistrationScope.map((draft) => {
                const vid = (context.certificationInquiryVestigingId[draft.id] ?? "").trim();
                const ve = context.onboardingVestigingen.find((x) => x.id === vid);
                if (!ve) {
                  return null;
                }
                return (
                  <section
                    key={draft.id}
                    className={personFormCardClassName("emphasized")}
                    aria-labelledby={`${legalEntityFieldBase}-inq-${draft.id}-title`}
                  >
                    <div className="space-y-1 border-b border-border pb-4">
                      <h4
                        id={`${legalEntityFieldBase}-inq-${draft.id}-title`}
                        className="text-sm font-semibold tracking-tight text-foreground"
                      >
                        {draft.shortLabel || draft.label}
                      </h4>
                      <div className="text-xs text-muted-foreground [&_.font-medium]:text-foreground">
                        <DraftCardDescription draft={draft} />
                      </div>
                      <p className="pt-2 text-xs text-muted-foreground">
                        Toegewezen voor registratie:{" "}
                        <span className="font-medium text-foreground">
                          {formatVestigingRegistryOptionLabel(ve)}
                        </span>
                      </p>
                    </div>
                    <div className="flex flex-wrap items-start justify-between gap-3 pt-4">
                      <p className="text-xs leading-relaxed text-muted-foreground">
                        Juridische entiteit voor deze certificatieaanvraag
                      </p>
                      <SubformCompletionBadge
                        complete={isOnboardingVestigingCaptureComplete(ve)}
                        showIncompletePlaceholder
                      />
                    </div>
                    <Field>
                      <FieldLabel htmlFor={`${legalEntityFieldBase}-ve-name-${ve.id}`}>
                        Handels- of juridische naam van de vestiging
                      </FieldLabel>
                      <FieldContent>
                        <Input
                          id={`${legalEntityFieldBase}-ve-name-${ve.id}`}
                          value={ve.legalName}
                          placeholder="Bv. naam van deze vestigingseenheid"
                          onChange={(e) =>
                            patchContext({
                              onboardingVestigingen: context.onboardingVestigingen.map((x) =>
                                x.id === ve.id ? { ...x, legalName: e.target.value } : x,
                              ),
                            })
                          }
                        />
                      </FieldContent>
                    </Field>
                    <IdentificatieAddressSubform
                      idPrefix={`ves-${ve.id}`}
                      value={vestigingAddressSubformValue(ve)}
                      onChange={(v) => {
                        const iso = registrationIsoCodeFromDutchCountryLabel(v.country.trim()) || "";
                        patchContext({
                          onboardingVestigingen: context.onboardingVestigingen.map((x) =>
                            x.id === ve.id
                              ? {
                                  ...x,
                                  addressStreet: v.street,
                                  addressHouseNumber: v.houseNumber,
                                  addressPostalCode: v.postalCode,
                                  addressCity: v.locality,
                                  country: v.country,
                                  addressCountryCode: iso,
                                }
                              : x,
                          ),
                        });
                      }}
                      countryOptions={countrySelectOptions}
                      countrySelectValue={
                        ve.country.trim() && countrySelectOptions.includes(ve.country.trim())
                          ? ve.country.trim()
                          : COUNTRY_SELECT_NONE
                      }
                      onCountryChange={(cv) =>
                        patchContext({
                          onboardingVestigingen: context.onboardingVestigingen.map((x) =>
                            x.id === ve.id ? { ...x, country: cv === COUNTRY_SELECT_NONE ? "" : cv } : x,
                          ),
                        })
                      }
                      countrySelectMode="editable"
                      showCountryCodeField={false}
                    />
                  </section>
                );
              })}
            </div>
          </div>
        ) : null}
      </div>
    </>
  );
}

